module Counter_4bit_Asynch_Clr_b (  output [3: 0]  A, output next_stage, input Count_enable, Clk, Clear_b);  wire A0, A1, A2, A3;  assign A[3: 0] = {A3, A2, A1, A0};  wire J0, K0, J1, K1, J2, K2, J3, K3;  assign K0 = J0;  assign K1 = J1;  assign K2 = J2;  assign K3 = J3;  JK_FF M0 (A0, J0, K0, Clk, Clear_b);  JK_FF M1 (A1, J1, K1, Clk, Clear_b);  JK_FF M2 (A2, J2, K2, Clk, Clear_b);  JK_FF M3 (A3, J3, K3, Clk, Clear_b);  and (J0, Count_enable, Clear_b);  and (J1, J0, A0);  and (J2, J1, A1);  and (J3, J2, A2);  and (next_stage, A3, J3);endmoduleentity JK_FF is		port (Q: buffer bit; J, K, clock, Clear_b: in bit);end JK_FF;architecture Behavioral of JK_FF is  process  (clock, Clear_b) begin    	if (Clear_b = '0') then Q <= '0';    	elsif clock'event and clock = '1' then    		case (J & K) is      			when "00" =>		Q <= Q;      			when "01" =>		Q <= '0';      			when "10" =>		Q <= '1';      			when "11" =>		Q <= not Q;			end case;		end if;end Behavioral;module t_Counter_4bit_Asynch_Clr_b ();  wire [3: 0]  A;  wire next_stage;  reg Count_enable, Clk, Clear_b;  Counter_4bit_Asynch_Clr_b M0 (A, next_stage, Count_enable, Clk, Clear_b);  initial #200 $finish;  initial begin Clk = 0; forever #5 Clk = ~Clk; end  initial fork    Count_enable = 0;    Clear_b = 0;    #30 Count_enable = 1;    #50 Clear_b = 1;    #90 Count_enable = 0;    #110 Count_enable= 1;    #150 Clear_b = 0;    #170 Clear_b = 1;   joinendmodule